# Lanternhold v140: turn party invites off (John, 27 Nov 2026: "allows them to turn off invites from players").
# Paste into AWS CloudShell (us-east-1). Needs John's go. Run AFTER v140-exploits.sh (heroes must be that version).
#  - invite: POST /invite {act:'solo', on} sets/clears noinv on your hero row (on: waiting invites are declined);
#            asking a hero with noinv gets 409 solo; GET /invites returns solo.
#  - heroes: board rows carry ni (invites off) so the Guild shows "Solo" instead of Invite.
# Ship the v140 game right after (an older game cannot turn it on, so nothing breaks before that).
set -e
TS=$(date -u +%Y%m%d%H%M); mkdir -p ~/lhbak ~/lhv140i && cd ~/lhv140i
live() { curl -s -o live-$1.zip "$(aws lambda get-function --function-name $1 --query Code.Location --output text)"; unzip -p live-$1.zip index.js | md5sum | cut -c1-32; }
[ "$(live lanternhold-heroes)" = "b15a8589b6593007bbeabb2ef0306ffd" ] || { echo "lanternhold-heroes is not the v140-exploits code. Stopping; nothing changed."; exit 1; }
live lanternhold-invite >/dev/null; unzip -p live-lanternhold-invite.zip index.js | grep -q '#d' || { echo "lanternhold-invite is not the code expected (no #d hotfix). Stopping; nothing changed."; exit 1; }
echo "live code checked"
UNDO=""
put() {
  F=$1; D=$2
  cp live-$F.zip ~/lhbak/$F-$TS.zip
  [ "$(md5sum $D/index.js | cut -c1-32)" = "$3" ] || { echo "$F: the code did not paste cleanly. Stopping."; exit 1; }
  rm -f $D.zip && (cd $D && zip -qj ../$D.zip index.js)
  aws lambda update-function-code --function-name $F --zip-file fileb://$D.zip >/dev/null
  aws lambda wait function-updated --function-name $F
  UNDO="$UNDO\naws lambda update-function-code --function-name $F --zip-file fileb://$HOME/lhbak/$F-$TS.zip"
  echo "updated $F"
}
mkdir -p heroes && echo  | base64 -d > heroes/index.js
put lanternhold-heroes heroes 32585cee1326389248ae606e0a10bba2
mkdir -p invite && echo  | base64 -d > invite/index.js
put lanternhold-invite invite f009a0fedca572f7195770896de7e91f
curl -s -o /dev/null -w "GET /invites without sign-in: %{http_code} (401 is right)\n" https://nyu3u8gc73.execute-api.us-east-1.amazonaws.com/invites
echo "done. Backups in ~/lhbak/*-$TS.zip. Undo:"; echo -e "$UNDO"
